    /** Right after he died: every item just spawned around him is his. */
    public static void markOwnDrops(ClaudeEntity g) {
        if (!(g.level() instanceof ServerLevel level)) return;
        int n = 0;
        for (var it : level.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class, g.getBoundingBox().inflate(6), i -> i.isAlive() && i.getAge() <= 2)) { ownDrops().put(it.getUUID(), g.tickCount); n++; }
        ownDrops().values().removeIf(t -> g.tickCount - t > 20 * 60 * 6); // (despawned long ago anyway)
        if (n > 0) ClaudeMod.LOGGER.info("[Claude life] {} of his piles on the ground where he died: he knows they're his", n);
        if (n > 0) com.claudemod.entity.life.Clocks.pile(g, level); // his clock on them starts now
    }

    /** His own things lying about within r blocks (alive, not something he gave away). */
    public static List<net.minecraft.world.entity.item.ItemEntity> ownDropsNear(ClaudeEntity g, ServerLevel level, double r) {
        if (ownDrops == null || ownDrops.isEmpty()) return List.of();
        return level.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class, g.getBoundingBox().inflate(r), i -> i.isAlive() && ownDrops.containsKey(i.getUUID()) && !g.isGift(i));
    }
    /** One of his own dropped things (he knows when it fell: its clock is his to read). */
    public static boolean ownDrop(ClaudeEntity g, net.minecraft.world.entity.item.ItemEntity i) { return ownDrops != null && ownDrops.containsKey(i.getUUID()) && !g.isGift(i); }

