    /** A test's clean slate: the gate's memory of him. */
    public static void gateReset(ClaudeEntity g) { java.util.UUID u = g.getUUID(); gateWhy().remove(u); saidNotGeared().remove(u); lastSafe().remove(u); if (gearShort != null) gearShort.remove(u); if (gearSaid != null) gearSaid.remove(u); }
    private static void gateNote(ClaudeEntity g, String why) { if (!why.equals(gateWhy().put(g.getUUID(), why))) ClaudeMod.LOGGER.info("[Claude life] notGearedForThere: {}", why); }

    /**
     * Following them into a place he has SEEN is dangerous (a mineshaft's rails and cobwebs, a trial chamber's tuff bricks were in
     * his view), short of that place's own gear bar ({@link Kit#bar}): a player waits outside and says what he lacks, in player
     * words. Never for his own mine, whatever a structure's box overlaps; never for a place known only from the server's structure
     * data. True when the walk to them should not happen; if he's already inside such a place he heads back to the last safe spot.
     */
    public static boolean notGearedForThere(ClaudeEntity g, ServerPlayer player) {
        var here = Structures.seenDangerAt(g, g.blockPosition());
        if (here == null) lastSafe().put(g.getUUID(), g.blockPosition().immutable());
        BlockPos ts = theirSpot(g, player); // (where he knows them to be)
        if (ts == null) { gateNote(g, "no gate: he doesn't know where they are"); return false; }
        if (ownMine(g, ts)) { gateNote(g, "no gate: they're at " + ts.toShortString() + ", in his own mine"); return false; }
        var there = Structures.seenDangerAt(g, ts);
        if (there == null) { gateNote(g, "no gate: nothing dangerous he has seen where they are (" + ts.toShortString() + ")"); return false; }
        Kit.Bar bar = Kit.bar(there.id());
        if (bar == null) { gateNote(g, "no gate: they're in " + there.id() + " at " + ts.toShortString() + ", traps not mobs: no gear bar"); return false; }
        var lack = Kit.shortOf(g, bar);
        if (lack.isEmpty()) { gateNote(g, "geared for " + bar.place() + " (seen at " + there.saw().toShortString() + "): in after them to " + ts.toShortString()); return false; }
        String need = Kit.join(lack);
        if (gearShort == null) gearShort = new java.util.HashMap<>();
        gearShort.put(g.getUUID(), bar.place() + " (need " + need + ")");
        gateNote(g, "they're at " + ts.toShortString() + " in " + bar.place() + " he saw at " + there.saw().toShortString() + ", short of its bar (" + need + "; " + bar.why() + "): waiting outside");
        if (Math.abs(g.tickCount - saidNotGeared().getOrDefault(g.getUUID(), -100000)) > 20 * 120) {
            saidNotGeared().put(g.getUUID(), g.tickCount);
            String line = "i'm not geared up for " + bar.place() + " yet: i'd want " + need + " first. i'll wait out here";
            if (gearSaid == null) gearSaid = new java.util.HashMap<>();
            gearSaid.put(g.getUUID(), line);
            ClaudeChat.say(player, line, "caution");
        }
        if (here != null && g.tasks.isEmpty() && g.currentTask == null) { // already in there: back out to where it was safe
            BlockPos safe = lastSafe().get(g.getUUID());
            if (safe != null && safe.distSqr(g.blockPosition()) > 4) { g.tasks.add(new Task.GoTo(safe, 2)); ClaudeMod.LOGGER.info("[Claude life] notGearedForThere: inside {} short of its gear: back out to {}", bar.place(), safe.toShortString()); }
        }
        return true;
    }

    /** The water's edge, a beach, or below sea level: no place for a mine entrance. */
    static boolean wetSite(ServerLevel level, BlockPos at) {
        if (shoreBiome(level, at)) return true; // a beach, a river bank, the sea: no place for a mine entrance (a desert's sand is fine)
        for (BlockPos q : BlockPos.betweenClosed(at.offset(-8, -9, -8), at.offset(8, 1, 8))) if (!level.getFluidState(q).isEmpty()) return true; // (as far as the first 8 steps of stairs reach: 8 out, 8 down)
        return false;
    }

    /** Beach, stony shore, river or ocean biome here (by the game's own tags and names). */
    static boolean shoreBiome(ServerLevel level, BlockPos at) {
        var b = level.getBiome(at);
        if (b.is(net.minecraft.tags.BiomeTags.IS_BEACH) || b.is(net.minecraft.tags.BiomeTags.IS_RIVER) || b.is(net.minecraft.tags.BiomeTags.IS_OCEAN) || b.is(net.minecraft.tags.BiomeTags.IS_DEEP_OCEAN)) return true;
        String name = b.unwrapKey().map(k -> k.location().getPath()).orElse("");
        return name.contains("beach") || name.contains("shore") || name.contains("river") || name.contains("ocean");
    }

    /** Dry, standable ground within 24 of here (8+ away, above sea level, no water within 6, not sand or gravel, not beside a build), nearest first. */
    static BlockPos drySpotNear(ClaudeEntity g, ServerPlayer player, ServerLevel level, BlockPos at) {
        BlockPos dry = null; double best = Double.MAX_VALUE;
        for (BlockPos p0 : BlockPos.betweenClosed(at.offset(-24, -6, -24), at.offset(24, 12, 24))) {
            double dd = p0.distSqr(at);
            if (dd < 8 * 8 || dd >= best || !standable(level, p0)) continue;
            if (shoreBiome(level, p0)) continue;
            { Integer failed = g.attempts.any.get(p0); if (failed != null && g.tickCount - failed < 20 * 300) continue; } // a spot he just failed to get up to: not picked again (two of them, back and forth for 3 minutes)
            boolean wet = false;
            for (BlockPos q : BlockPos.betweenClosed(p0.offset(-10, -11, -10), p0.offset(10, 3, 10))) if (!level.getFluidState(q).isEmpty()) { wet = true; break; } // (the first 8 steps of stairs go 8 out and 8 down; 2 more all round so where he actually stops, a block or two off, still passes wetSite: he flipped between two "dry" spots that each read wet on arrival)
            if (wet || nearestBuild(g, player, p0, 6) != null) continue;
            best = dd; dry = p0.immutable();
        }
        return dry;
    }

    /** Up to 96 blocks out in 8 directions: the nearest spot that's not beach, river or sea, up on dry ground; null when it's water all round. */
    static BlockPos inlandSpot(ServerLevel level, BlockPos at) {
        BlockPos best = null; double bd = Double.MAX_VALUE;
        for (Direction d : Direction.Plane.HORIZONTAL) for (int diag = 0; diag < 2; diag++) {
            int dx = d.getStepX() + (diag == 1 ? d.getClockWise().getStepX() : 0), dz = d.getStepZ() + (diag == 1 ? d.getClockWise().getStepZ() : 0);
            for (int dist = 16; dist <= 96; dist += 8) {
                int x = at.getX() + dx * dist, z = at.getZ() + dz * dist;
                if (!level.isLoaded(new BlockPos(x, 64, z))) break;
                int y = level.getHeight(net.minecraft.world.level.levelgen.Heightmap.Types.MOTION_BLOCKING_NO_LEAVES, x, z);
                BlockPos p = new BlockPos(x, y, z);
                if (y < level.getSeaLevel() + 3 || shoreBiome(level, p) || !level.getFluidState(p.below()).isEmpty()) continue;
                boolean wet = false;
                for (BlockPos q : BlockPos.betweenClosed(p.offset(-8, -9, -8), p.offset(8, 1, 8))) if (!level.getFluidState(q).isEmpty()) { wet = true; break; }
                if (wet) continue;
                double dd = p.distSqr(at);
                if (dd < bd) { bd = dd; best = p.immutable(); }
                break; // the first dry spot out this way is the one (further is just further)
            }
        }
        return best;
    }

    /** The table he put down a moment ago just to craft on: back in his pocket right after, like a player carrying his table (unless they said to leave stations). */
    static void repocketTable(ClaudeEntity g, ServerLevel level) {
        if ("no".equals(g.pref("pick_up_stations", "yes"))) return; // (no 30-second limit: a chain of crafts ran past it and the table stayed out, litter at -194, 68, 110; the temp-station check below is what makes it his)
        BlockPos table = findNear(level, g.blockPosition(), 5, b -> b.is(Blocks.CRAFTING_TABLE));
        if (table == null || !g.tempStations.contains(table)) return;
        if (g.skillQueue.stream().anyMatch(st -> st.skill().equals("craft"))) return; // more crafting queued: it stays till that's done
        g.tasks.addFirst(new Task.Pickup(40));
        g.tasks.addFirst(new Task.Break(table.immutable()));
        g.tablePlacedTick = -100000;
        ClaudeMod.LOGGER.info("[Claude life] done at the table at {}: back in his pocket", table.toShortString());
    }

    private static int dropLogTick = -100000; // ponytail: one Claude per server
    /** Drops what he's doing right now (it was re-queued by the caller if it still matters), naming the line that did it when it keeps happening. */
    public static void dropCurrent(ClaudeEntity g) {
        g.dropCurrent = true;
        if (g.tickCount - dropLogTick >= 20) { // (a line a second at most)
            dropLogTick = g.tickCount;
            var st = Thread.currentThread().getStackTrace();
            ClaudeMod.LOGGER.info("[Claude life] dropping the current task ({}) at {}:{}", g.currentTask == null ? "-" : g.currentTask.getClass().getSimpleName(), st.length > 2 ? st[2].getFileName() : "?", st.length > 2 ? st[2].getLineNumber() : 0);
        }
    }

    /** Wipes his queued work, saying so in the log with the line that did it (silent wipes cost hours of reading). */
    public static void clearTasks(ClaudeEntity g) {
        var cover = g.coverTasks(); // the cover he's sitting in (its wait, the lid out, the climb up) stays: a job switch at night took his hole's exit and at first light he was three down under his lid, 160 walks at the rock
        int kept = 0; for (Task t : g.tasks) if (cover.stream().anyMatch(x -> x == t)) kept++;
        if (!g.tasks.isEmpty()) {
            var st = Thread.currentThread().getStackTrace();
            ClaudeMod.LOGGER.info("[Claude life] dropping {} queued tasks (first: {}) at {}:{}{}", g.tasks.size() - kept, g.tasks.peek().getClass().getSimpleName(), st.length > 2 ? st[2].getFileName() : "?", st.length > 2 ? st[2].getLineNumber() : 0, kept > 0 ? " (keeping " + kept + " of the cover he's in: out of it first)" : "");
        }
        if (kept == 0) g.tasks.clear(); else g.tasks.removeIf(t -> cover.stream().noneMatch(x -> x == t));
    }

    /**
     * Night cover in his own mine. Down there already (a row of it, under rock): that's cover, nothing to dig. Up top within 24 of
     * its door with nothing on him: in he goes, down to the first dug row under rock that's lit or dark to the sky, never a hole by
     * it (he dug one in his own doorway). Null: not that (no mine, too far, a mob on him: the hole/tower rules decide).
     */
    static String shelterInMine(ClaudeEntity g, ServerLevel level) {
        MineBlueprint b = g.blueprint;
        if (!bpMode(g) || b == null || b.isEmpty()) return null;
        BlockPos at = g.blockPosition();
        boolean inRows = b.rowOf(at) >= 0 || b.rowOf(at.above()) >= 0;
        if (inRows && !level.canSeeSky(at.above()) && b.rowOf(at) != 0) return "done: down my mine already, under rock: that's cover (nothing to dig)";
        if (b.entrance.distSqr(at) > 24 * 24) return null;
        if (!com.claudemod.entity.life.Perception.known(g, net.minecraft.world.entity.monster.Monster.class, g.getBoundingBox().inflate(6), m -> m.isAlive() && !(m instanceof net.minecraft.world.entity.monster.RangedAttackMob)).isEmpty()) return null; // one in close: no walk with it on his back (the cover proximity rule)
        int dug = b.dugMainRows(level), k = 0; BlockPos dest = null;
        for (MineBlueprint.Row r : b.rows()) {
            var kind = b.segments.get(r.segment()).kind;
            if (kind == MineBlueprint.Kind.BRANCH || kind == MineBlueprint.Kind.RUN) continue;
            if (k >= dug) break;
            BlockPos f = r.first();
            if (k++ >= 2 && !level.canSeeSky(f.above()) && (level.getBrightness(net.minecraft.world.level.LightLayer.SKY, f) < 4 || level.getBrightness(net.minecraft.world.level.LightLayer.BLOCK, f) >= 8)) { dest = f; break; }
        }
        if (dest == null) return null;
        clearTasks(g); dropCurrent(g);
        bpWalkTo(g, dest);
        ClaudeMod.LOGGER.info("[Claude life] night cover: his mine is {} blocks off, into it (down to {}), not a hole by it", (int) Math.sqrt(b.entrance.distSqr(at)), dest.toShortString());
        return "night: into my mine for cover, down to " + dest.toShortString();
    }

