                    if (level.getBlockState(under).getCollisionShape(level, under).isEmpty()) { pyramidInChamber = true; g.skillQueue.addFirst(new Skills.Step("loot", "desert_pyramid@2", count, st.where())); return "dropping into the chamber"; }
                    if (under.getY() < pyramidCol.getY() - 14) return "failed: 14 down beside the shaft and no chamber: the trap room is elsewhere";
                    int gap = 0; for (BlockPos q = under.below(); gap < 6 && level.getBlockState(q).getCollisionShape(level, q).isEmpty(); q = q.below()) gap++;
                    if (gap >= 2) pyramidInChamber = true; // the room is under this block: the drop is the last step of the column
                    safeDrops().add(under.immutable()); // the chamber under the last block is 3 high: a player drops it, no damage
                    pyramidSteps++;
