                mobs.removeIf(e -> !g.hasLineOfSight(e) && (e.getY() < g.getY() - 3 || e.getY() > g.getY() + 3)); // one under the floor or up a shaft he can't see: not a fight he can get to (he'd stand there swinging at rock)
