    /** A crafting table within a player's reach of his eyes (4.5 blocks to the block), or null: crafting on a table happens at the table. */
    public static BlockPos tableInReach(ClaudeEntity g, ServerLevel level) {
        BlockPos best = null; double bd = Double.MAX_VALUE;
        for (BlockPos p : BlockPos.betweenClosed(g.blockPosition().offset(-5, -3, -5), g.blockPosition().offset(5, 3, 5))) {
            if (!level.getBlockState(p).is(Blocks.CRAFTING_TABLE)) continue;
            double d = new net.minecraft.world.phys.AABB(p).distanceToSqr(g.getEyePosition());
            if (d <= 4.5 * 4.5 && d < bd) { bd = d; best = p.immutable(); }
        }
        return best;
    }

    /** Falling with a water bucket: once the ground is within reach, water under his feet, the way a player MLGs a fall (and the fall does nothing). */
    static void mlg(ClaudeEntity g, ServerLevel level) {
        if (g.onGround() || g.isInWater() || g.fallDistance < 2.5f || g.getDeltaMovement().y > -0.3) return;
        if (g.inventory.count(s -> s.is(Items.WATER_BUCKET)) == 0) return;
        BlockPos ground = null; int drop = 0;
        for (BlockPos q = g.blockPosition().below(); drop < 6; q = q.below(), drop++) {
            if (!level.getFluidState(q).isEmpty()) return; // water or lava below: water lands him anyway, lava is another story (he'd have steered off it)
            if (!level.getBlockState(q).getCollisionShape(level, q).isEmpty()) { ground = q; break; }
        }
        if (ground == null || drop > 3) return; // not in reach yet (4.5 from the eyes), or nothing to land on this side of the void
        if (g.fallDistance + drop < 6 || isCastBlock(ground) || isCastBlock(ground.above())) return; // a short drop is just taken (a player doesn't throw his water for a 4-block hop); coming down his casting pillar never (the bucket's water landed on the ground by the frame and the pit ran dry)
        if (!g.hold(s -> s.is(Items.WATER_BUCKET))) return;
        Vec3 hit = Vec3.atCenterOf(ground).add(0, 0.5, 0);
        g.getLookControl().faceNow(hit);
        if (g.useHeld()) ClaudeMod.LOGGER.info("[Claude life] falling ({} blocks so far): water bucket under his feet on {}", (int) g.fallDistance, ground.toShortString());
    }

    /** An empty bucket and a water source within reach: fill it (a right-click on the water), like a player topping up before the mine; also takes back the water he threw under himself. */
    static void fillBucket(ClaudeEntity g, ServerLevel level) {
        if (portalSlots != null && !portalSlots.isEmpty()) return; // mid-cast the bucket's state is the cast's business
        if (g.inventory.count(s -> s.is(Items.BUCKET)) == 0 || g.inventory.count(s -> s.is(Items.WATER_BUCKET)) > 0 || g.isUsingItem() || g.currentTask instanceof Task.Attack || g.currentTask instanceof Task.Flee) return;
        BlockPos best = null; double bd = 4.0 * 4.0;
        for (BlockPos q : BlockPos.betweenClosed(g.blockPosition().offset(-3, -2, -3), g.blockPosition().offset(3, 1, 3))) {
            var f = level.getFluidState(q);
            if (!f.is(net.minecraft.tags.FluidTags.WATER) || !f.isSource()) continue;
            if (g.farm != null && g.farm.waterCells().contains(q)) continue; // his farm's water: there on purpose
            if (Primitives.pouredOnAsk(g, q) || com.claudemod.entity.life.LessonWords.lessonWater(g, null, level, q)) { if (g.tickCount % 200 < 5) ClaudeMod.LOGGER.info("[Claude life] the water at {} is the one they had him pour: leaving it (ClaudeLife.fillBucket)", q.toShortString()); continue; } // (scoop_at takes it back)
            double d = Vec3.atCenterOf(q).distanceToSqr(g.getEyePosition());
            if (d < bd) { bd = d; best = q.immutable(); }
        }
        if (best == null || !g.hold(s -> s.is(Items.BUCKET))) return;
        g.getLookControl().faceNow(Vec3.atCenterOf(best));
        g.useHeld(); // (the bucket's own ray from his eyes: a block in the way and nothing happens, like for anyone)
        if (g.inventory.count(s -> s.is(Items.WATER_BUCKET)) > 0) ClaudeMod.LOGGER.info("[Claude life] filled his bucket at {}", best.toShortString());
    }

