    private static java.util.Set<BlockPos> safeDrops; // blocks under his feet a loot routine may dig out despite the drop under them (a room he knows is 3 high)
    public static boolean safeDrop(BlockPos p) { return safeDrops != null && safeDrops.contains(p); }
