    private static int pyramidSteps, treasureSteps, pyramidOut, pyramidOff; // pyramidOut/Off: rounds spent getting into / centred in the column, each reset when that holds (they shared the dig's count) // how far down a side column / a treasure dig has gone
    private static BlockPos pyramidCol; // the side column he's digging (the cell beside the trap shaft)
    private static BlockPos pyramidBlue; // the blue terracotta: the shaft, and the plate, are under it
    private static boolean pyramidInChamber; // dropped into the trap room: no more digging there
    public static boolean testBeach; // gametest: the box has no beach biome; the (9,9) rule is what's under test
    public static String lastTreasureCalc = ""; // the last "treasure rule" line, for the test to read

    /** What a chest's stack is worth to him: which to take first when the pockets fill, whether a chest is worth a detour. */
    public static int lootValue(ItemStack s) {
        if (s.isEmpty()) return 0;
        Item it = s.getItem();
        int per = it == Items.ENCHANTED_GOLDEN_APPLE ? 60 : it == Items.DIAMOND ? 40 : it == Items.ENCHANTED_BOOK ? 30 : it == Items.ENDER_PEARL ? 30 : it == Items.FLINT_AND_STEEL ? 25 : it == Items.GOLDEN_APPLE ? 20
                : it == Items.BUCKET || it == Items.WATER_BUCKET ? 15 : it == Items.FIRE_CHARGE ? 12 : it == Items.SADDLE ? 10 : it == Items.OBSIDIAN ? 8 : it == Items.EMERALD ? 8 : it == Items.TNT ? 8
                : it == Items.IRON_INGOT || it == Items.GOLD_INGOT || it == Items.RAW_IRON ? 6 : it == Items.NAME_TAG ? 6 : it == Items.STRING ? 2 : it == Items.ARROW ? 1 : it == Items.IRON_NUGGET || it == Items.GOLD_NUGGET ? 1 : 0;
        if (per == 0 && (it instanceof net.minecraft.world.item.TieredItem || it instanceof net.minecraft.world.item.ArmorItem || it instanceof net.minecraft.world.item.BowItem || it instanceof net.minecraft.world.item.CrossbowItem)) per = 12;
        if (per == 0 && (it instanceof net.minecraft.world.item.PotionItem || it == Items.FILLED_MAP || it == Items.MAP)) per = 10;
        if (per == 0 && s.has(net.minecraft.core.component.DataComponents.FOOD) && it != Items.ROTTEN_FLESH && it != Items.SPIDER_EYE && it != Items.POISONOUS_POTATO) per = 3;
        return per * s.getCount();
    }

    /** A player's call on a chest's stack: take it or leave it (junk stays: seeds past a handful, dyes, bones when he's fed, gravel). */
    public static boolean worthTaking(ClaudeEntity g, ItemStack s) {
        if (s.isEmpty()) return false;
        Item it = s.getItem();
        if (lootValue(s) > 0) return true;
        if (it == Items.LEATHER) return g.inventory.count(x -> x.is(Items.LEATHER)) < 8;
        if (it == Items.WHEAT_SEEDS || it == Items.BEETROOT_SEEDS) return g.inventory.count(x -> x.is(it)) < 16;
        if (it == Items.BONE || it == Items.ROTTEN_FLESH) return g.inventory.count(x -> x.has(net.minecraft.core.component.DataComponents.FOOD)) < 4;
        return it == Items.WHEAT || it == Items.COAL || it == Items.CHARCOAL || it == Items.TORCH || it == Items.FLINT || it == Items.FEATHER || it == Items.PAPER || it == Items.BOOK || it == Items.LAPIS_LAZULI || it == Items.REDSTONE || it == Items.GUNPOWDER || it == Items.GOLD_NUGGET;
    }

    /** Chests and barrels he can actually see from where he stands (a player loots what's in view, not what the world data lists); never one the user placed; a double chest once. */
    public static List<BlockPos> visibleChests(ClaudeEntity g, ServerLevel level, ServerPlayer them, int r) {
        List<BlockPos> out = new ArrayList<>();
        List<BlockPos> theirs = them == null ? List.of() : PlayerProfile.placedBy(them);
        for (BlockPos p : BlockPos.betweenClosed(g.blockPosition().offset(-r, -r / 2, -r), g.blockPosition().offset(r, r / 2, r))) {
            BlockState st = level.getBlockState(p);
            if (!(st.getBlock() instanceof net.minecraft.world.level.block.ChestBlock) && !st.is(Blocks.BARREL)) continue;
            if (lootedChests().contains(p) || theirs.contains(p) || !visibleBlock(g, level, p)) continue;
            { BlockPos other = st.getBlock() instanceof net.minecraft.world.level.block.ChestBlock && st.getValue(net.minecraft.world.level.block.ChestBlock.TYPE) != net.minecraft.world.level.block.state.properties.ChestType.SINGLE ? p.relative(net.minecraft.world.level.block.ChestBlock.getConnectedDirection(st)) : p;
              if (g.myStations.contains(p) || g.storageChests.contains(p) || g.myStations.contains(other) || g.storageChests.contains(other)) continue; } // his own chests are never loot (he "looted the ruined portal" out of his own nook's storage)
            if (st.getBlock() instanceof net.minecraft.world.level.block.ChestBlock && st.getValue(net.minecraft.world.level.block.ChestBlock.TYPE) == net.minecraft.world.level.block.state.properties.ChestType.LEFT) continue; // one click opens both halves
            out.add(p.immutable());
        }
        out.sort(Comparator.comparingDouble(p -> p.distSqr(g.blockPosition())));
        return out;
    }

    public static void makeRoom(ClaudeEntity g) { dumpJunk(g); }

    /** A spot under water becomes the surface over it: he swims there and looks down, like a player over a wreck. */
    static BlockPos surfaceOver(ServerLevel level, BlockPos p) {
        int n = 0; while ((!level.getFluidState(p).isEmpty() || !level.getBlockState(p).getCollisionShape(level, p).isEmpty()) && n++ < 32) p = p.above();
        return p;
    }

    /** Line of sight to a block that isn't a full cube (a chest, a bed, a pressure plate): a ray from his eyes to its centre against the outline shapes, within 24. */
    public static boolean visibleBlock(ClaudeEntity g, ServerLevel level, BlockPos b) {
        Vec3 eye = g.getEyePosition(), c = Vec3.atCenterOf(b);
        var shape = level.getBlockState(b).getShape(level, b);
        if (!shape.isEmpty()) c = shape.bounds().getCenter().add(b.getX(), b.getY(), b.getZ()); // a plate's centre is a sixteenth off the floor, not half a block up
        if (eye.distanceTo(c) > 24) return false;
        var hit = level.clip(new ClipContext(eye, c, ClipContext.Block.OUTLINE, ClipContext.Fluid.NONE, g));
        return hit.getType() == HitResult.Type.BLOCK && hit.getBlockPos().equals(b);
    }

