                    if (!holding(g, Items.LAVA_BUCKET)) { String stray = strayLava(g, level, slot); if (stray != null) { again.run(); return stray; } portalStep = 5; again.run(); return "no lava in the bucket: down for some"; }
                    if (Math.abs(g.getY() - base.above(steps).getY()) > 0.5) { portalStep = 2; again.run(); return "off the pillar (at " + g.blockPosition().toShortString() + ", top " + base.above(steps).toShortString() + "): up it again before the pour"; }
