                    g.hold(s -> s.is(Items.LAVA_BUCKET)); g.getLookControl().faceNow(Vec3.atCenterOf(slot).add(back.getStepX() * 0.45, -0.2, back.getStepZ() * 0.45)); g.useHeld(); // at the cell's back, low: over the front wall's top edge, onto the back wall's inner face (the cell's centre sat behind that edge: lava on top of the front wall every time)
                    if (level.getFluidState(slot).is(net.minecraft.tags.FluidTags.LAVA)) { portalStep = 5; again.run(); return "lava in " + slot.toShortString(); }
                    if (!holding(g, Items.LAVA_BUCKET)) { String stray = strayLava(g, level, slot); if (stray != null) { again.run(); return stray; } }
