    static String bpNewLevel(ClaudeEntity g, ServerLevel level, MineBlueprint b, int bestY, String ore, int oldY) {
        if (!BEST_Y.containsKey(ore)) return null; // (cobble comes out of any tunnel: no new level for it)
        java.util.Set<Integer> levels = new java.util.HashSet<>(); for (MineBlueprint.Segment s0 : b.segments) if (s0.kind == MineBlueprint.Kind.FLAT || s0.kind == MineBlueprint.Kind.RUN || s0.kind == MineBlueprint.Kind.BRANCH) levels.add(s0.start.getY());
        List<MineBlueprint.Row> rs = b.rows(); List<Integer> steps = new ArrayList<>();
        for (int i = 0; i < rs.size(); i++) { MineBlueprint.Row r = rs.get(i); int y = r.first().getY();
            if (b.segments.get(r.segment()).kind != MineBlueprint.Kind.STAIRS || Math.abs(y - bestY) > 12 || levels.stream().anyMatch(v -> Math.abs(v - y) < 5)) continue;
            if (java.util.Arrays.stream(r.feet()).anyMatch(f -> MineBlueprint.solid(level, f) || MineBlueprint.solid(level, f.above()))) continue; // (a step not dug yet)
            steps.add(i); }
        steps.sort(java.util.Comparator.comparingInt(i -> Math.abs(rs.get(i).first().getY() - bestY)));
        for (int i : steps) { MineBlueprint.Row r = rs.get(i); Direction rr = r.dir().getClockWise(); int y = r.first().getY();
            for (Direction side : new Direction[] {rr, rr.getOpposite()}) {
                BlockPos st = (side == rr ? r.feet()[r.feet().length - 1] : r.feet()[0]).relative(side);
                Integer tried = g.attempts.any.get(st.below(700)); if (tried != null && g.tickCount - tried < 20 * 300) continue;
                boolean bad = false; Direction cw = side.getClockWise();
                for (int k = 0; k <= 12 && !bad; k++) for (int w0 = -2; w0 <= b.width + 1 && !bad; w0++) for (int y0 = -1; y0 <= 3 && !bad; y0++) { BlockPos q = st.relative(side, k).relative(cw, w0).above(y0);
                    if (com.claudemod.entity.life.Perception.knowsWater(g, q)) bad = true; // (the aquifer that took his old level, or another: never a level into water)
                    else if (k <= 8 && w0 >= 0 && w0 < b.width && y0 >= 0 && y0 < 3 && (b.isWalk(q) || lavaNear(g, level, q))) bad = true; } // (his own tunnels or lava in the way)
                for (int k = 0; k < 4 && !bad; k++) for (int w0 = -1; w0 <= b.width && !bad; w0++) for (int y0 = -1; y0 < 3 && !bad; y0++) { BlockPos q = st.relative(side, k).relative(cw, w0).above(y0); var qs = level.getBlockState(q); if (qs.hasBlockEntity() || qs.is(Blocks.CRAFTING_TABLE) || qs.is(BlockTags.BEDS) || g.myStations.contains(q) || g.storageChests.contains(q) || anyNookTouches(g, q)) bad = true; }
                if (bad) continue;
                g.attempts.any.put(st.below(700).immutable(), g.tickCount);
                MineBlueprint.Segment run = new MineBlueprint.Segment(MineBlueprint.Kind.RUN, st, side, 0, null);
                b.segments.add(run); b.invalidate();
                String line = bpOpenRun(g, level, b, y, ore);
                if (line == null) { b.segments.remove(run); b.invalidate(); bpSync(g); continue; }
                if (run.n == 0) return line; // (an older run at that y went on instead)
                ClaudeMod.LOGGER.info("[Claude life] blueprint: no room at his {} level{}: a new level off his stairs at y {} ({} from {}): {}", ore, oldY == Integer.MIN_VALUE ? "" : " (y " + oldY + ")", y, side.getName(), st.toShortString(), line);
                return "a new " + ore + " level off my stairs at y=" + y + (oldY == Integer.MIN_VALUE ? "" : " (no room left at my y=" + oldY + " level)") + ": a tunnel " + side.getName() + " " + run.n + " rows";
            }
        }
        return null;
    }

    /** How far his branches off the level's first tunnel reach, plus two: a second tunnel's pairs start past that. */
    static int levelReach(MineBlueprint b, int levelY) {
        int reach = 0; List<MineBlueprint.Row> rs = b.rows();
        for (MineBlueprint.Segment s0 : b.segments) if (s0.kind == MineBlueprint.Kind.BRANCH && s0.start.getY() == levelY) { int ri = b.rowOf(s0.start.relative(s0.dir.getOpposite())); if (ri >= 0 && b.segments.get(rs.get(ri).segment()).kind == MineBlueprint.Kind.FLAT) reach = Math.max(reach, s0.n); }
        return reach + 2;
    }

    /**
     * More of the level when its tunnel has no room left (every slot branched, the branches at 32 or plugged): a second tunnel at the
     * same y off the level's first two rows, to one side then the other, 8 rows a round, out past the old branches and 32 rows on
     * (pairs come off it in bpAtLevel like off the first). Undug rows of it are finished first; lava ends it. Null: both sides done.
     */
    static String bpOpenRun(ClaudeEntity g, ServerLevel level, MineBlueprint b, int levelY, String ore) {
        if (levelY == Integer.MIN_VALUE) return null;
        MineBlueprint.Segment flat = null; for (MineBlueprint.Segment s0 : b.segments) if (s0.kind == MineBlueprint.Kind.FLAT && s0.start.getY() == levelY && s0.n >= 2) { flat = s0; break; }
        int reach = levelReach(b, levelY), max = reach + 32;
        List<MineBlueprint.Segment> cands = new ArrayList<>();
        for (MineBlueprint.Segment s0 : b.segments) if (s0.kind == MineBlueprint.Kind.RUN && s0.start.getY() == levelY && s0.n < max) cands.add(s0);
        if (flat != null) for (int k0 = 0; k0 + 1 < Math.max(2, flat.n); k0 += 4) for (Direction side : new Direction[] {flat.dir.getClockWise(), flat.dir.getCounterClockWise()}) { // its first two rows' side wall: the new tunnel's mouth; further along the level when that wall is taken (his furnace wall stood there and the level read as done: iron at -58, the user)
            BlockPos st = side == flat.dir.getClockWise() ? flat.start.relative(flat.dir, k0 + 1).relative(side, b.width) : flat.start.relative(flat.dir, k0).relative(side);
            boolean wet = false; for (int k1 = 1; k1 <= 8 && !wet; k1++) for (int w0 = -2; w0 <= 2 && !wet; w0++) for (int y0 = -1; y0 <= 3 && !wet; y0++) { BlockPos q = st.relative(side, k1).relative(side.getClockWise(), w0).above(y0); if (com.claudemod.entity.life.Perception.knowsWater(g, q)) wet = true; } // an aquifer in the way: not a tunnel into it (a second run off his coal level went into the same water the first one ended at: 4 minutes plugging it)
            if (!wet && b.segments.stream().noneMatch(s0 -> s0.kind == MineBlueprint.Kind.RUN && s0.start.equals(st)) && !runByNook(g, b, st, side)) cands.add(new MineBlueprint.Segment(MineBlueprint.Kind.RUN, st, side, 0, null));
            if (b.segments.stream().anyMatch(s0 -> s0.kind == MineBlueprint.Kind.RUN && s0.start.getY() == levelY && s0.n < max)) break; // (one open run at a time)
        }
        for (MineBlueprint.Segment run : cands) {
            boolean fresh = !b.segments.contains(run);
            if (fresh) { b.segments.add(run); b.invalidate(); }
            int si = b.segments.indexOf(run); List<MineBlueprint.Row> rs = b.rows(); List<Integer> mine = new ArrayList<>();
            for (int i = 0; i < rs.size(); i++) if (rs.get(i).segment() == si) mine.add(i);
            int dug = 0; for (int i : mine) { if (java.util.Arrays.stream(rs.get(i).feet()).anyMatch(f -> MineBlueprint.solid(level, f) || MineBlueprint.solid(level, f.above()))) break; dug++; }
            if (dug >= run.n) { // all dug: 8 rows more, short of his own tunnels and lava he knows of
                for (int k = 0; k < 8 && run.n < max; k++) {
                    BlockPos f0 = run.start.relative(run.dir, run.n); boolean stop = false;
                    for (int c0 = 0; c0 < b.width && !stop; c0++) for (int y = 0; y < 3 && !stop; y++) { BlockPos q = f0.relative(run.dir.getClockWise(), c0).above(y); stop = b.isWalk(q) || lavaNear(g, level, q) || com.claudemod.entity.life.Perception.knowsWater(g, q) || java.util.Arrays.stream(Direction.values()).anyMatch(d9 -> com.claudemod.entity.life.Perception.knowsWater(g, q.relative(d9))) /* (water beside the next cell too: he'd plugged the one in line and the tunnel went on into the pocket round it) */ || level.getBlockState(q).hasBlockEntity() || level.getBlockState(q).is(Blocks.CRAFTING_TABLE); } // (and never through his own furnace, chest or table: the tunnel opened on his mine furnace and he stood at it 2 min)
                    if (stop) break;
                    run.n++; b.invalidate();
                }
            } else if (dug >= mine.size() || lavaNear(g, level, rs.get(mine.get(dug)).first()) || java.util.Arrays.stream(rs.get(mine.get(dug)).feet()).anyMatch(f -> { for (int y = 0; y < 3; y++) { var bs = level.getBlockState(f.above(y)); if (level.getFluidState(f.above(y)).is(net.minecraft.tags.FluidTags.WATER) || level.getFluidState(f.above(y).east()).is(net.minecraft.tags.FluidTags.WATER) || level.getFluidState(f.above(y).west()).is(net.minecraft.tags.FluidTags.WATER) || level.getFluidState(f.above(y).north()).is(net.minecraft.tags.FluidTags.WATER) || level.getFluidState(f.above(y).south()).is(net.minecraft.tags.FluidTags.WATER) /* (beside it too) */ /* (an aquifer: the run ends dry and walled, never re-fixed under the flow; 7 minutes plugging his coal tunnel at y 16) */ || bs.hasBlockEntity() || bs.is(Blocks.CRAFTING_TABLE)) return true; } return false; })) { run.n = dug; b.invalidate(); } // lava, or his own furnace/chest/table, at its undug end: the tunnel ends there
            if (run.n == dug) { if (fresh) { b.segments.remove(run); b.invalidate(); } continue; } // nothing to dig this way
            bpSync(g);
            rs = b.rows(); si = b.segments.indexOf(run); int first = -1, last = -1, lastDug = -1;
            for (int i = 0; i < rs.size(); i++) if (rs.get(i).segment() == si) { if (rs.get(i).index() < dug) lastDug = i; else { if (first < 0) first = i; last = i; } }
            bpWalkTo(g, lastDug >= 0 ? rs.get(lastDug).first() : flat != null ? flat.start : run.start.relative(run.dir.getOpposite()));
            int n = bpReconcile(g, level, first, last, false);
            g.tasks.add(new Task.MineVisibleOres(3)); g.tasks.add(new Task.Pickup(20));
            ClaudeMod.LOGGER.info("[Claude life] blueprint: his {} level (y {}) out of room: {} tunnel {} from {} on to {} rows (pairs past {}), {} task(s): {}", ore, levelY, fresh ? "a second" : "his second", run.dir.getName(), run.start.toShortString(), run.n, reach, n, b);
            return "more of my " + ore + " level: " + (fresh ? "a new tunnel off it " : "my second tunnel on ") + run.dir.getName() + " to " + run.n + " rows";
        }
        return null;
    }

    /** His chests and furnaces are part of his inventory (the user's rule): what's in them, by item (chests whole, furnaces' output), within 48 blocks. */
    public static java.util.Map<Item, Integer> stored(ClaudeEntity g, ServerLevel level) {
        java.util.Map<Item, Integer> m = new java.util.HashMap<>(com.claudemod.entity.life.ChestLedger.totals(g, level)); // his chests as of his last look in each, from anywhere (the user: "does he know he have 7 diamonds": 190 off, past the old 48, they counted as none)
        for (BlockPos p : g.myStations) { // his furnaces' output, close by
            if (!level.isLoaded(p) || p.distSqr(g.blockPosition()) > 48 * 48) continue;
            if (level.getBlockEntity(p) instanceof net.minecraft.world.level.block.entity.AbstractFurnaceBlockEntity f && !f.getItem(2).isEmpty()) m.merge(f.getItem(2).getItem(), f.getItem(2).getCount(), Integer::sum);
        }
        return m;
    }

    // ---- wear / take_off: a player's own armor clicks (live 17:54: "gold boots on" in diamond boots, Overworld: no skill, and equipArmor put the best back every 5 s)
    /** The slot's standing choice from their wear / take_off: an item id, "none", or null. */
    private static String pinned(ClaudeEntity g, net.minecraft.world.entity.EquipmentSlot sl) {
        if (g.wornChoice == null) g.wornChoice = ""; // (a field added live starts null)
        for (String p : g.wornChoice.split(";")) if (p.startsWith(sl.getName() + "=")) return p.substring(sl.getName().length() + 1);
        return null;
    }
    private static void pin(ClaudeEntity g, net.minecraft.world.entity.EquipmentSlot sl, String what) {
        StringBuilder sb = new StringBuilder();
        for (String p : (g.wornChoice == null ? "" : g.wornChoice).split(";")) if (!p.isEmpty() && !p.startsWith(sl.getName() + "=")) sb.append(p).append(';');
        if (what != null) sb.append(sl.getName()).append('=').append(what).append(';');
        g.wornChoice = sb.toString();
    }
    /** True while their choice for this slot stands (equipArmor leaves it alone); a chosen piece that's gone ends it. */
    static boolean held(ClaudeEntity g, net.minecraft.world.entity.EquipmentSlot sl) {
        String p = pinned(g, sl);
        if (p == null) return false;
        ItemStack w = g.getItemBySlot(sl);
        if (p.equals("none") ? w.isEmpty() : net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(w.getItem()).toString().equals(p)) return true;
        pin(g, sl, null);
        ClaudeMod.LOGGER.info("[Claude life] their {} choice ({}) ended: {} there now, the best he has goes back on (ClaudeLife.held)", sl.getName(), p, w.isEmpty() ? "nothing" : w.getHoverName().getString());
        return false;
    }
    /** wear <piece|shield> (off false) / take_off <piece> (off true): the swap on the spot, as a player clicks the slot; the slot then stays as they chose. */
    static String wear(ClaudeEntity g, ServerLevel level, Skills.Step st, String target, boolean off) {
        Item item = item(target);
        if (item == null || item == Items.AIR) return "failed: I don't know an item called " + target;
        var sl = g.getEquipmentSlotForItem(new ItemStack(item));
        if (sl == net.minecraft.world.entity.EquipmentSlot.MAINHAND) return "failed: " + target + " isn't something you wear (it goes in your hand)";
        String id = net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(item).toString();
        ItemStack worn = g.getItemBySlot(sl);
        if (off) {
            if (!worn.is(item)) return "done: I'm not wearing " + target + " (" + (worn.isEmpty() ? "nothing" : worn.getHoverName().getString()) + " in that slot)";
            if (!g.inventory.hasRoomFor(worn)) return "failed: no room in my pack for my " + target + " (store or toss something first)";
            g.inventory.add(worn.copy()); g.setItemSlot(sl, ItemStack.EMPTY); pin(g, sl, "none");
            ClaudeMod.LOGGER.info("[Claude life] take_off {}: into his pack, his {} slot left empty till they say (ClaudeLife.wear)", target, sl.getName());
            return "done: took my " + target + " off, it's in my pack; that slot stays empty till you say";
        }
        if (worn.is(item)) { pin(g, sl, id); return "done: already wearing " + target + " (it stays on till you say)"; }
        int at = -1;
        for (int i = 0; i < g.inventory.items.getContainerSize(); i++) if (g.inventory.items.getItem(i).is(item)) { at = i; break; }
        if (at < 0) {
            String fetch = fromMyChests(g, level, t -> t.is(item), st); if (fetch != null) return fetch;
            return "failed: no " + target + " on me or in my chests (make or get one first)";
        }
        g.setItemSlot(sl, g.inventory.items.getItem(at).copy()); g.inventory.items.setItem(at, worn.copy()); pin(g, sl, id);
        ClaudeMod.LOGGER.info("[Claude life] wear {}: on in his {} slot, {} into his pack; the best-armor rule leaves that slot alone till they say or it breaks (ClaudeLife.wear)", target, sl.getName(), worn.isEmpty() ? "nothing" : worn.getHoverName().getString());
        return "done: " + target + " on" + (worn.isEmpty() ? "" : ", my " + worn.getHoverName().getString().toLowerCase() + " in my pack") + "; it stays on till you say";
    }

    /** Wears the best armor he is carrying, and a shield in his off hand. */
    private static void equipArmor(ClaudeEntity g) {
        if (!held(g, net.minecraft.world.entity.EquipmentSlot.OFFHAND) && !g.getItemBySlot(net.minecraft.world.entity.EquipmentSlot.OFFHAND).is(Items.SHIELD)) {
            for (int i = 0; i < g.inventory.items.getContainerSize(); i++) {
                ItemStack s = g.inventory.items.getItem(i);
                if (!s.is(Items.SHIELD)) continue;
                ItemStack off = g.getItemBySlot(net.minecraft.world.entity.EquipmentSlot.OFFHAND);
                g.setItemSlot(net.minecraft.world.entity.EquipmentSlot.OFFHAND, s.copy());
                g.inventory.items.setItem(i, off.copy());
                break;
            }
        }
        boolean nether = g.level().dimension() == net.minecraft.world.level.Level.NETHER; // (piglins: one gold piece on in the Nether beats a point of armor; the user, 16:26 "so put them on")
        boolean goldOn = false; for (var sl : net.minecraft.world.entity.EquipmentSlot.values()) if (sl.isArmor() && g.getItemBySlot(sl).getItem() instanceof net.minecraft.world.item.ArmorItem a0 && a0.getMaterial().is(net.minecraft.world.item.ArmorMaterials.GOLD)) goldOn = true;
        for (int i = 0; i < g.inventory.items.getContainerSize(); i++) {
            ItemStack s = g.inventory.items.getItem(i);
            if (!(s.getItem() instanceof net.minecraft.world.item.ArmorItem armor)) continue;
            var slot = armor.getEquipmentSlot();
            if (held(g, slot)) continue; // their wear / take_off choice stands
            ItemStack worn = g.getItemBySlot(slot);
            int wornDef = worn.getItem() instanceof net.minecraft.world.item.ArmorItem w ? w.getDefense() : 0;
            boolean isGold = armor.getMaterial().is(net.minecraft.world.item.ArmorMaterials.GOLD);
            if (nether && worn.getItem() instanceof net.minecraft.world.item.ArmorItem w1 && w1.getMaterial().is(net.minecraft.world.item.ArmorMaterials.GOLD)) continue; // his gold piece stays on in the Nether
            if (nether && !goldOn && isGold || armor.getDefense() > wornDef) {
                if (isGold) goldOn = true;
                g.setItemSlot(slot, s.copy());
                g.inventory.items.setItem(i, worn.copy());
            }
        }
    }


    // ---------------------------------------------------------------- his own place

    /** A 5x5 shack, door gap facing their bed. Each call places the next dozen blocks. */
    /** Returns what happened, so the planner can tell "no blocks" from "no spot" from "done". */
    private static String buildBase(ClaudeEntity g, ServerPlayer player) {
        ServerLevel level = player.serverLevel();
        if (houseMode(g)) return hbBuild(g, player, level, g.lastStep == null ? new Skills.Step("build_my_place", "", 1) : g.lastStep);
        BlockPos origin = PlayerProfile.baseOrigin(player);
        BlockPos anchor = bed(player) != null ? bed(player) : theirOr(g, player);
        if (origin == null || Math.sqrt(origin.distSqr(anchor)) > 80) {
            origin = pickBaseSite(level, player);
            if (origin == null) return "failed: no flat open spot near them to build on (try build_here somewhere flatter)";
            PlayerProfile.setBaseOrigin(player, origin);
        }
        BlockPos bed = bed(player);
        Direction front = bed == null ? Direction.NORTH : Direction.getNearest(bed.getX() - origin.getX(), 0, bed.getZ() - origin.getZ());
        int placed = buildShack(g, player, origin, front);
        if (placed < 0) {
            int inside = furnishHome(g, player, origin, front);
            if (inside > 0) return "the walls and roof stand: furnishing my place (" + inside + " things to set inside: door, bed, chest, table, furnace, torch)";
            note(g, player, "finished building your place, facing their bed");
            return "done: your place is already finished. Your goal is complete: choose a new goal";
        }
        return placed == 0 ? "failed: no building blocks you're allowed to use (no dirt/sand/gravel unless they asked; get cobblestone or logs)"
                : "building more of your place (" + placed + " blocks this round)";
    }

    /**
     * Cooks this step plus every other smelt step in the plan at once, like a player with a furnace row:
     * batches of 8 (one coal each) spread over up to 4 furnaces, all loaded first, then collected.
     */
    private static String smeltInParallel(ClaudeEntity g, ServerPlayer player, ServerLevel level, Skills.Step st, BlockPos first) {
        List<Skills.Step> jobs = new ArrayList<>(List.of(st));
        g.skillQueue.removeIf(s -> s.skill().equals("smelt") && jobs.add(s));
        List<Object[]> loads = new ArrayList<>(); // [input, count] per smelt job
        List<String> names = new ArrayList<>();
        int est = 0;
        for (Skills.Step job : jobs) {
            Item out = item(job.target().toLowerCase().replace("minecraft:", "").trim().replace(' ', '_'));
            Item input = out == null ? null : smeltInput(level, g, out);
            if (input == null) continue;
            int n = Math.min(job.count(), g.inventory.count(t -> t.is(input)));
            if (n <= 0) continue;
            names.add(n + " " + Crafting.name(input));
            loads.add(new Object[] {input, n}); est += (n + 7) / 8;
        }
        if (loads.isEmpty()) return "failed: nothing to smelt";
        // furnaces: every one around (the user's wall of six), plus new ones if he has the cobblestone (one per 8 items, max 4 placed)
        List<BlockPos> furnaces = new ArrayList<>(findAll(level, first, 6, b -> b.is(Blocks.FURNACE), 6)); // the user: six furnaces at a time, never more (64 copper had him put a seventh in his mine wall)
        if (!furnaces.contains(first)) { furnaces.add(0, first); if (furnaces.size() > 6) furnaces.remove(furnaces.size() - 1); }
        boolean table = findNear(level, g.blockPosition(), 5, b -> b.is(Blocks.CRAFTING_TABLE)) != null;
        if (!table && furnaces.size() < Math.min(6, est) && g.inventory.count(t -> t.is(Items.FURNACE)) == 0 && g.inventory.count(t -> t.is(ItemTags.STONE_CRAFTING_MATERIALS)) >= 8 && g.inventory.count(t -> t.is(Items.CRAFTING_TABLE)) > 0) { // the table on him goes down for the extra furnaces (one furnace for 1 log, 8 cod and 21 logs in a row: 5 min stood watching, 212 cobble and a table on him, live 11:24)
            BlockPos tp = placeNextTo(g, level, Items.CRAFTING_TABLE); table = tp != null;
            ClaudeMod.LOGGER.info("[Claude life] {} smelt jobs for one furnace: {} (ClaudeLife.smeltInParallel)", est, tp != null ? "his table down at " + tp.toShortString() + " for more furnaces" : "no spot for his table, one furnace it is");
        }
        while (furnaces.size() < Math.min(6, est)) { // (the user: every furnace at once, the load split; this is the cap on new ones he places, 12 like findAll above)
            if (g.inventory.count(t -> t.is(Items.FURNACE)) == 0
                    && (!table || Crafting.craft(level, g.inventory, Items.FURNACE, 1, true).made() == 0)) break;
            BlockPos extra = placeNextTo(g, level, Items.FURNACE);
            if (extra == null) break;
            furnaces.add(extra);
        }
        // batches: each job split evenly over all the furnaces (the user: all of them at once, in groups): 32 raw iron in six furnaces is 6,6,5,5,5,5, not 8,8,8,8
        List<Object[]> batches = new ArrayList<>();
        for (Object[] l : loads) {
            int n = (int) l[1], parts = Math.max(1, Math.min(furnaces.size(), (n + 7) / 8)); // the user: a furnace per 8 (one coal's worth), never one item each in six furnaces burning six fuels
            for (int k = 0; k < parts; k++) { int c = n / parts + (k < n % parts ? 1 : 0); if (c > 0) batches.add(new Object[] {l[0], c}); }
        }
        // assign: a furnace takes one kind of item; same-kind batches can share
        Item[] kind = new Item[furnaces.size()];
        int[] load = new int[furnaces.size()];
        List<Object[]> later = new ArrayList<>();
        for (Object[] b : batches) {
            Item input = (Item) b[0];
            int best = -1;
            for (int i = 0; i < furnaces.size(); i++) {
                if (kind[i] != null && kind[i] != input) continue;
                if (best < 0 || load[i] < load[best]) best = i;
            }
            if (best < 0) { later.add(b); continue; }
            kind[best] = input;
            load[best] += (int) b[1];
        }
        for (int i = 0; i < furnaces.size(); i++) if (kind[i] != null) g.tasks.add(new Task.FurnaceLoad(furnaces.get(i), kind[i], load[i]));
        for (int i = 0; i < furnaces.size(); i++) if (kind[i] != null) g.tasks.add(new Task.FurnaceTake(furnaces.get(i)));
        for (Object[] b : later) { g.tasks.add(new Task.FurnaceLoad(furnaces.get(0), (Item) b[0], (int) b[1])); g.tasks.add(new Task.FurnaceTake(furnaces.get(0))); } // more kinds than furnaces: each after the batch before it is out, as a load and a take (the take is where a short job nearby fits in; a plain Smelt stood him at the furnace the whole time)
        int used = (int) java.util.Arrays.stream(kind).filter(java.util.Objects::nonNull).count();
        return "smelting " + String.join(" and ", names) + " in " + used + " furnace" + (used == 1 ? "" : "s") + " at once";
    }

    private static final Item[] PICKAXES = {Items.WOODEN_PICKAXE, Items.STONE_PICKAXE, Items.IRON_PICKAXE, Items.DIAMOND_PICKAXE};
    private static final Item[] AXES = {Items.WOODEN_AXE, Items.STONE_AXE, Items.IRON_AXE, Items.DIAMOND_AXE};
    private static final Item[] SHOVELS = {Items.WOODEN_SHOVEL, Items.STONE_SHOVEL, Items.IRON_SHOVEL, Items.DIAMOND_SHOVEL};
    private static final Item[] SWORDS = {Items.DIAMOND_SWORD, Items.IRON_SWORD, Items.STONE_SWORD, Items.WOODEN_SWORD}; // best first

    /**
     * Like a player: before a job that needs a tool he doesn't have (stone without a pickaxe, iron ore with a
     * wooden one), make the cheapest one that works. If he's short on materials, go get them first (wood,
     * cobblestone, iron), craft it, then come back to this step. Returns null when he's good to go, or what
     * he's doing instead (the step is re-queued behind it).
     */
    private static String ensureToolFor(ClaudeEntity g, ServerPlayer player, ServerLevel level, BlockState state, Skills.Step st) {
        if (!state.requiresCorrectToolForDrops()) return null;
        if (!g.inventory.find(t -> t.isCorrectToolForDrops(state)).isEmpty()) return null;
        Item[] kinds = state.is(BlockTags.MINEABLE_WITH_PICKAXE) ? PICKAXES : state.is(BlockTags.MINEABLE_WITH_AXE) ? AXES
                : state.is(BlockTags.MINEABLE_WITH_SHOVEL) ? SHOVELS : null;
        if (kinds == null) return null;
        Item tool = null;
        for (Item k : kinds) if (new ItemStack(k).isCorrectToolForDrops(state)) { tool = k; break; } // cheapest tier that works
        if (tool == null) return "failed: no tool you can make mines " + BuiltInRegistries.BLOCK.getKey(state.getBlock()).getPath();
        String name = Crafting.name(tool);
        // Try now with what he has (at a table already standing nearby if there is one).
        String walking = goToStation(g, level, Blocks.CRAFTING_TABLE, st);
        if (walking != null) return walking;
        boolean table = ensureCraftingTable(g, level, tool);
        if (g.tablePlacedTick == g.tickCount) {
            g.tasks.add(new Task.Wait(3, false));
            g.skillQueue.addFirst(st);
            return "put down a crafting table to make a " + name;
        }
        if (Crafting.craft(level, g.inventory, tool, 1, table).made() > 0) {
            ClaudeMod.LOGGER.info("[Claude skill] made a {} for the job", name);
            return null;
        }
        // Short on materials: get them, make it, then back to this. (Each of these steps gets its own tool the same way.)
        List<Skills.Step> pre = new ArrayList<>();
        int wood = g.inventory.count(s -> s.is(ItemTags.LOGS)) * 4 + g.inventory.count(s -> s.is(ItemTags.PLANKS)) + g.inventory.count(s -> s.is(Items.STICK)) / 2;
        String tier = name.substring(0, name.indexOf('_'));
        int head = 3; // ponytail: 3 covers a pickaxe/axe head; a shovel needs 1, extra is fine
        switch (tier) {
            case "wooden" -> { if (wood < 6) pre.add(new Skills.Step("collect", "logs", 3)); }
            case "stone" -> {
                int cobble = g.inventory.count(s -> s.is(ItemTags.STONE_TOOL_MATERIALS));
                if (cobble < head) pre.add(new Skills.Step("collect", "cobblestone", head - cobble + 2));
            }
            case "iron" -> {
                int ingots = g.inventory.count(s -> s.is(Items.IRON_INGOT)), raw = g.inventory.count(s -> s.is(Items.RAW_IRON));
                if (ingots + raw < head) pre.add(new Skills.Step("strip_mine", "iron_ore", head - ingots - raw));
                if (ingots < head) pre.add(new Skills.Step("smelt", "iron_ingot", head - ingots));
            }
            case "diamond" -> {
                int dia = g.inventory.count(s -> s.is(Items.DIAMOND));
                if (dia < head) pre.add(new Skills.Step("strip_mine", "diamond_ore", head - dia));
            }
            default -> { }
        }
        if (wood < 2 && !tier.equals("wooden")) pre.add(new Skills.Step("collect", "logs", 2)); // sticks
        g.skillQueue.addFirst(st);
        g.skillQueue.addFirst(new Skills.Step("craft", name, 1));
        for (int i = pre.size() - 1; i >= 0; i--) g.skillQueue.addFirst(pre.get(i));
        ClaudeMod.LOGGER.info("[Claude skill] needs a {} first: {}", name, pre);
        return "need a " + name + " for this first, so getting what it takes";
    }

    /** Before a fight: make the best sword he can from what he carries (no detours; a fight can't wait). */
    /** Diamonds are theirs while they've asked for diamonds or diamond gear; otherwise, on his own, he spends them like any player. */
    static boolean diamondsReserved(ClaudeEntity g) {
        String goal = (g.playerGoal == null ? "" : g.playerGoal).toLowerCase();
        String ongoing = g.prefs.getOrDefault("ongoing_job", "").toLowerCase();
        return (goal.contains("diamond") && !goal.startsWith("done")) || ongoing.contains("diamond");
    }

    private static java.util.Map<java.util.UUID, Integer> swordTry; // (static: fields added live start null)
    private static java.util.Map<java.util.UUID, Integer> swordTry() { if (swordTry == null) swordTry = new java.util.HashMap<>(); return swordTry; }
    private static java.util.Map<java.util.UUID, Integer> swordSig; // what he had to make one from, last try
    private static java.util.Map<java.util.UUID, Integer> swordSig() { if (swordSig == null) swordSig = new java.util.HashMap<>(); return swordSig; }

    public static void craftSwordIfCan(ClaudeEntity g, ServerLevel level) {
        int sig = g.inventory.count(s -> s.is(ItemTags.LOGS)) * 1000003 + g.inventory.count(s -> s.is(ItemTags.PLANKS)) * 10007 + g.inventory.count(s -> s.is(ItemTags.STONE_TOOL_MATERIALS)) * 101 + g.inventory.count(s -> s.is(Items.IRON_INGOT)); // what a sword could come from
        if (Math.abs(g.tickCount - swordTry().getOrDefault(g.getUUID(), -100000)) < 100 && swordSig().getOrDefault(g.getUUID(), -1) == sig) return; // tried a moment ago with the same stuff: nothing's changed
        swordTry().put(g.getUUID(), g.tickCount); swordSig().put(g.getUUID(), sig);
        // his best sword so far (damage goes up with the tier); only make one that beats it
        int haveTier = -1;
        for (int i = 0; i < SWORDS.length; i++) { final Item s0 = SWORDS[i]; if (g.inventory.count(s -> s.is(s0)) > 0) { haveTier = SWORDS.length - 1 - i; break; } }
        // the best he could make from what he's carrying; nothing better than what he has means no table goes down for it
        int canTier = g.inventory.count(s -> s.is(Items.IRON_INGOT)) >= 2 ? 2 : g.inventory.count(s -> s.is(ItemTags.STONE_TOOL_MATERIALS)) >= 2 ? 1
                : g.inventory.count(s -> s.is(ItemTags.PLANKS)) + 4 * g.inventory.count(s -> s.is(ItemTags.LOGS)) >= 4 ? 0 : -1;
        if (canTier <= haveTier) return;
        // a sword takes a table: one goes down right here if he has none in reach, like a player (picked up again when he moves on)
        boolean table = ensureCraftingTable(g, level, Items.STONE_SWORD);
        for (int i = 0; i < SWORDS.length; i++) {
            Item sword = SWORDS[i];
            if (SWORDS.length - 1 - i <= haveTier) return;
            if (sword == Items.DIAMOND_SWORD && diamondsReserved(g)) continue; // they asked for diamonds: those are theirs, not his sword
            if (Crafting.craft(level, g.inventory, sword, 1, table).made() == 0) continue;
            ClaudeMod.LOGGER.info("[Claude skill] made a {} for the fight", Crafting.name(sword));
            return;
        }
    }

    /**
     * Before a job: if he can make a better tool for it from what he's carrying (an axe before chopping,
     * a stone pickaxe once he has cobblestone, iron once he has ingots), make it now. No detour for materials:
     * that's ensureToolFor's job when the tool is actually required.
     */
    private static void upgradeToolFor(ClaudeEntity g, ServerLevel level, BlockState state) {
        Item[] kinds = state.is(BlockTags.MINEABLE_WITH_PICKAXE) ? PICKAXES : state.is(BlockTags.MINEABLE_WITH_AXE) ? AXES
                : state.is(BlockTags.MINEABLE_WITH_SHOVEL) ? SHOVELS : null;
        if (kinds == null) return;
        float have = 1.0f; // bare hands
        for (int i = 0; i < g.inventory.items.getContainerSize(); i++) have = Math.max(have, g.inventory.items.getItem(i).getDestroySpeed(state));
        BlockPos tablePos = findNear(level, g.blockPosition(), 5, b -> b.is(Blocks.CRAFTING_TABLE));
        boolean table = tablePos != null;
        if (!table && g.inventory.count(s -> s.is(Items.CRAFTING_TABLE)) > 0) table = placeNextTo(g, level, Items.CRAFTING_TABLE) != null;
        if (!table && kinds == PICKAXES && have < new ItemStack(Items.STONE_PICKAXE).getDestroySpeed(state)) { // a wooden pick with 159 cobble on him for half an hour: a player spends a log on a table
            int rock = 0, wood = 0;
            for (int i = 0; i < g.inventory.items.getContainerSize(); i++) { var it0 = g.inventory.items.getItem(i); if (it0.is(ItemTags.STONE_TOOL_MATERIALS)) rock += it0.getCount(); else if (it0.is(ItemTags.LOGS)) wood += it0.getCount() * 4; else if (it0.is(ItemTags.PLANKS)) wood += it0.getCount(); }
            if (rock >= 3 && wood >= 8 && Crafting.craft(level, g.inventory, Items.CRAFTING_TABLE, 1, false).made() > 0) {
                table = placeNextTo(g, level, Items.CRAFTING_TABLE) != null;
                ClaudeMod.LOGGER.info("[Claude skill] no table about for a better pickaxe: made one ({} cobble on him)", rock);
            }
        }
        if (!table) return; // ponytail: tools need a table; only a real pickaxe upgrade is worth a new one
        int top = diamondsReserved(g) ? 2 : 3; // the best he can make, like any player; diamonds only while they haven't asked for them
        if (kinds != PICKAXES && g.inventory.count(s -> s.is(Items.IRON_INGOT)) < 27 && Kit.missing(g, true).keySet().stream().anyMatch(k -> Crafting.name(k).startsWith("iron"))) top = Math.min(top, 1); // the first iron goes on armor and a sword, not an axe or shovel (a stone one chops fine)
        for (int i = top; i >= 0; i--) { // best first
            Item t = kinds[i];
            if (new ItemStack(t).getDestroySpeed(state) <= have) break; // nothing better than what he has
            if (Crafting.craft(level, g.inventory, t, 1, true).made() > 0) {
                ClaudeMod.LOGGER.info("[Claude skill] made a {} before getting to work", Crafting.name(t));
                return;
            }
        }
        // A mining trip: a spare pickaxe along, like a player, so a broken one doesn't send him back up
        if (kinds == PICKAXES && g.inventory.count(s -> s.getItem() instanceof net.minecraft.world.item.PickaxeItem) < 2) {
            for (int i = 1; i >= 1; i--) { // a stone one: a spare wooden one is just waste, a spare iron one wastes iron
                if (Crafting.craft(level, g.inventory, kinds[i], 1, true).made() > 0) {
                    ClaudeMod.LOGGER.info("[Claude skill] made a spare {} for the trip", Crafting.name(kinds[i]));
                    return;
                }
            }
        }
    }

    /**
     * Logs ordered the way a player works a forest: one log per tree (its trunk base), starting with the tree
     * nearest him, then always the nearest tree left from the one he just finished.
     */
    private static List<BlockPos> routeTrees(ServerLevel level, List<BlockPos> logs, BlockPos from) {
        java.util.LinkedHashSet<BlockPos> bases = new java.util.LinkedHashSet<>();
        for (BlockPos b : logs) {
            BlockPos base = b;
            while (level.getBlockState(base.below()).is(BlockTags.LOGS)) base = base.below();
            bases.add(base.immutable());
        }
        List<BlockPos> left = new ArrayList<>(bases), route = new ArrayList<>();
        BlockPos at = from;
        while (!left.isEmpty()) {
            final BlockPos here = at;
            BlockPos next = left.stream().min(Comparator.comparingDouble(p -> p.distSqr(here))).get();
            left.remove(next);
            route.add(next);
            at = next;
        }
        return route;
    }

    /**
     * A spot beside the upper trunk where he could stand and chop (open, solid floor, at most 2 below the top
     * log) that he can actually walk to from here. Null when there's none: then it's bottom up.
     */
    private static BlockPos perchBeside(ClaudeEntity g, ServerLevel level, BlockPos top) {
        List<BlockPos> spots = new ArrayList<>();
        for (BlockPos p : BlockPos.betweenClosed(top.offset(-2, -2, -2), top.offset(2, 0, 2))) {
            if (standable(level, p) && !level.getBlockState(p.below()).is(BlockTags.LEAVES)) spots.add(p.immutable()); // not in the canopy
        }
        spots.sort(Comparator.comparingDouble(p -> p.distSqr(top)));
        for (int i = 0; i < Math.min(6, spots.size()); i++) { // route searches are costly: the 6 best spots at most
            var path = g.getNavigation().createPath(spots.get(i), 0);
            if (path != null && path.canReach() && path.getNodeCount() < 60) return spots.get(i);
        }
        return null;
    }

    /** The nearest spot under treetops (leaves/logs on top of the surface) within range, scanning surface columns only. */
    private static BlockPos nearestTreetops(ServerLevel level, BlockPos from, int range) {
        BlockPos best = null;
        double bestD = Double.MAX_VALUE;
        for (int dx = -range; dx <= range; dx += 2) for (int dz = -range; dz <= range; dz += 2) {
            double dd = dx * dx + dz * dz;
            if (dd > range * range || dd >= bestD || dd < 8 * 8) continue; // (close by, the normal search already looked: a placed log isn't a tree)
            int x = from.getX() + dx, z = from.getZ() + dz;
            if (!level.hasChunkAt(new BlockPos(x, from.getY(), z))) continue;
            int top = level.getHeight(net.minecraft.world.level.levelgen.Heightmap.Types.MOTION_BLOCKING, x, z) - 1;
            BlockState s = level.getBlockState(new BlockPos(x, top, z));
            if (!s.is(BlockTags.LEAVES) && !s.is(BlockTags.LOGS)) continue;
            int ground = level.getHeight(net.minecraft.world.level.levelgen.Heightmap.Types.MOTION_BLOCKING_NO_LEAVES, x, z);
            best = new BlockPos(x, ground, z);
            bestD = dd;
        }
        return best;
    }

    /** Logs connected to a tree (26-neighbour, so diagonal branches count), not already in `skip`, lowest first. */
    public static List<BlockPos> wholeTree(ServerLevel level, BlockPos base, List<BlockPos> skip) {
        java.util.Set<BlockPos> seen = new java.util.HashSet<>(skip);
        java.util.ArrayDeque<BlockPos> todo = new java.util.ArrayDeque<>(skip);
        List<BlockPos> out = new ArrayList<>();
        while (!todo.isEmpty() && out.size() < 48) {
            BlockPos c = todo.poll();
            for (BlockPos n : BlockPos.betweenClosed(c.offset(-1, -1, -1), c.offset(1, 1, 1))) {
                if (Math.abs(n.getX() - base.getX()) > 7 || Math.abs(n.getZ() - base.getZ()) > 7 || n.getY() < base.getY()) continue; // not the next tree over
                if (!level.getBlockState(n).is(BlockTags.LOGS) || !seen.add(n.immutable())) continue;
                if (otherTrunk(level, n, base)) continue; // the next tree's trunk (dark oak canopies grow into each other): not this tree
                out.add(n.immutable());
                todo.add(n.immutable());
            }
        }
        out.sort(Comparator.comparingInt(BlockPos::getY));
        return out;
    }

    /** True if this log stands on a trunk that goes down to the ground somewhere else than this tree's foot. */
    private static boolean otherTrunk(ServerLevel level, BlockPos log, BlockPos base) {
        BlockPos b = log;
        while (b.getY() > base.getY() - 3 && level.getBlockState(b.below()).is(BlockTags.LOGS)) b = b.below();
        boolean grounded = level.getBlockState(b.below()).isFaceSturdy(level, b.below(), Direction.UP);
        boolean ours = Math.abs(b.getX() - base.getX()) <= 1 && Math.abs(b.getZ() - base.getZ()) <= 1; // a 2x2 trunk's other columns
        return grounded && !ours && b.getY() <= base.getY() + 2;
    }

    /** The item he carries the most of among those matching ok, or AIR. */
    private static Item mostOf(ClaudeEntity g, Predicate<ItemStack> ok) {
        Item best = net.minecraft.world.item.Items.AIR;
        int bestN = 0;
        for (int i = 0; i < g.inventory.items.getContainerSize(); i++) {
            ItemStack s = g.inventory.items.getItem(i);
            if (s.isEmpty() || !ok.test(s)) continue;
            Item it = s.getItem();
            int n = g.inventory.count(t -> t.is(it));
            if (n > bestN) { bestN = n; best = it; }
        }
        return best;
    }

    /** Queues the next dozen blocks of a 5x5 hut at origin. Returns blocks queued, or -1 if it is finished. */
    private static int buildShack(ClaudeEntity g, ServerPlayer player, BlockPos origin, Direction front) {
        ServerLevel level = player.serverLevel();
        // Keep wood for tools: never build with the last 2 logs or the last 8 planks.
        int logs = g.inventory.count(s -> s.is(ItemTags.LOGS));
        int planksWanted = Math.min(24, g.inventory.count(s -> s.is(ItemTags.PLANKS)) + Math.max(0, logs - 2) * 4);
        g.inventory.craftPlanks(planksWanted);
        int spareWood = Math.max(0, g.inventory.count(s -> s.is(ItemTags.PLANKS)) - 8);
        // Prefer plain blocks he doesn't need (cobblestone...) before spare planks. No dirt/sand/gravel huts unless they asked.
        String buildWith = g.pref("build_with", "");
        Item material = net.minecraft.world.item.Items.AIR;
        if (!buildWith.isBlank() && !buildWith.equals("anything")) { // they named a block: use only that
            var named = BuiltInRegistries.ITEM.get(net.minecraft.resources.ResourceLocation.withDefaultNamespace(buildWith.toLowerCase().replace(' ', '_')));
            if (named != net.minecraft.world.item.Items.AIR) material = mostOf(g, s -> s.is(named));
            if (buildWith.equals("dirt")) material = mostOf(g, s -> s.is(ItemTags.DIRT));
        } else {
            boolean anything = buildWith.equals("anything");
            // his biggest stack, not the first one he finds (one stray andesite used to block the whole build)
            material = mostOf(g, s -> ClaudeInventory.isBuildingBlock(s) && !s.is(ItemTags.PLANKS) && !s.is(ItemTags.LOGS)
                    && !s.is(net.minecraft.world.item.Items.CRAFTING_TABLE)
                    && (anything || !(s.is(ItemTags.DIRT) || s.is(ItemTags.SAND) || s.is(net.minecraft.world.item.Items.GRAVEL))));
        }
        { final Item m0 = material; if (m0 != net.minecraft.world.item.Items.AIR && buildWith.isBlank() && g.inventory.count(t -> t.is(m0)) < 4) material = net.minecraft.world.item.Items.AIR; } // (a stray couple of granite is not a building stock: it ended the build with 24 planks on him)
        if (material == net.minecraft.world.item.Items.AIR && spareWood > 0) material = mostOf(g, s -> s.is(ItemTags.PLANKS)); // his biggest planks stack (the first found was 2 birch among 26 planks: "no building blocks", the planner re-asked every 5 s)
        List<BlockPos> next = new ArrayList<>();
        for (BlockPos p : shack(origin, front)) {
            if (!level.getBlockState(p).canBeReplaced()) continue;
            Integer failedAt = g.attempts.any.get(p); // a gap he already tried and couldn't fill: not queued again every 30 s (it piled 120 tasks on his queue)
            if (failedAt != null && g.tickCount - failedAt < 20 * 300) continue;
            boolean queuedAlready = false;
            for (Task t : g.tasks) if (t instanceof Task.Place pl && pl.pos().equals(p)) { queuedAlready = true; break; }
            if (queuedAlready) continue;
            next.add(p);
            if (next.size() >= 12) break;
        }
        if (next.isEmpty()) return -1;
        if (material == net.minecraft.world.item.Items.AIR) return 0;
        final Item mat = material;
        int have = g.inventory.count(s -> s.is(mat));
        if (mat != net.minecraft.world.item.Items.AIR && have > 0 && new ItemStack(mat).is(ItemTags.PLANKS)) have = Math.min(have, spareWood);
        if (have < 4 && next.size() >= 4) return 0; // not worth a trip for one or two blocks
        g.tasks.add(new Task.GoTo(origin, 4));
        int queued = 0;
        for (BlockPos p : next) if (queued < have) { g.tasks.add(new Task.Place(p, mat)); queued++; }
        return queued;
    }

    /** The door that matches the planks he carries (any wood), crafted if he has none; null when he can't make one. */
    private static Item doorFor(ClaudeEntity g, ServerLevel level) {
        Item have = g.inventory.find(st -> st.getItem() instanceof net.minecraft.world.item.BlockItem bi && bi.getBlock() instanceof net.minecraft.world.level.block.DoorBlock).getItem();
        if (have != Items.AIR) return have;
        ItemStack planks = g.inventory.find(st -> st.is(ItemTags.PLANKS));
        if (planks.isEmpty() || planks.getCount() < 6) return null;
        Item door = BuiltInRegistries.ITEM.get(net.minecraft.resources.ResourceLocation.withDefaultNamespace(BuiltInRegistries.ITEM.getKey(planks.getItem()).getPath().replace("_planks", "_door")));
        if (door == Items.AIR) return null;
        boolean table = ensureCraftingTable(g, level, door);
        return Crafting.craft(level, g.inventory, door, 1, table).made() > 0 ? door : null;
    }

    /** The inside of his place: where each thing goes, relative to the door wall. */
    private static java.util.Map<String, BlockPos> homeLayout(BlockPos o, Direction front) {
        Direction back = front.getOpposite(), cw = front.getClockWise();
        java.util.Map<String, BlockPos> m = new java.util.LinkedHashMap<>();
        m.put("door", o.relative(front, 2));
        m.put("bed", o.relative(cw.getOpposite())); // foot at the left-middle, head in the back-left corner: set from the front-left cell, looking at the back wall
        m.put("chest", o.relative(back).relative(cw));
        m.put("table", o.relative(cw));
        m.put("furnace", o.relative(front).relative(cw));
        m.put("torch", o);
        return m;
    }

    /**
     * Once the walls and roof stand: a door in the gap, and inside a bed, a chest (his storage), a table, a furnace and a torch,
     * whatever of those he has on him. Returns how many he queued (0: furnished, or nothing on him to set).
     */
    private static int furnishHome(ClaudeEntity g, ServerPlayer player, BlockPos o, Direction front) {
        ServerLevel level = player.serverLevel();
        var at = homeLayout(o, front);
        java.util.function.Predicate<BlockPos> inside = q -> Math.abs(q.getX() - o.getX()) <= 1 && Math.abs(q.getZ() - o.getZ()) <= 1 && q.getY() >= o.getY() && q.getY() <= o.getY() + 2;
        int queued = 0;
        BlockPos door = at.get("door");
        if (!(level.getBlockState(door).getBlock() instanceof net.minecraft.world.level.block.DoorBlock) && level.getBlockState(door).canBeReplaced()) {
            Item d = doorFor(g, level);
            if (d != null) { g.tasks.add(new Task.GoTo(o.relative(front, 3), 1.5)); g.tasks.add(new Task.Place(door, d)); queued++; }
        }
        boolean bedIn = findAll(level, o, 2, b -> b.is(BlockTags.BEDS), 1).stream().anyMatch(inside);
        if (!bedIn && g.inventory.count(st -> st.is(ItemTags.BEDS)) > 0 && level.getBlockState(at.get("bed")).canBeReplaced()) {
            g.tasks.add(new Task.GoTo(o.relative(front), 0.6)); g.tasks.add(new Task.Place(at.get("bed"), g.inventory.find(st -> st.is(ItemTags.BEDS)).getItem())); queued++; // (from by the door, facing the back wall: the bed's head runs along it)
        }
        for (var e : java.util.Map.of("chest", Items.CHEST, "table", Items.CRAFTING_TABLE, "furnace", Items.FURNACE).entrySet()) {
            BlockPos q = at.get(e.getKey());
            Item it = e.getValue();
            boolean there = findAll(level, o, 2, b -> b.is(((net.minecraft.world.item.BlockItem) it).getBlock()), 1).stream().anyMatch(inside);
            if (there || !level.getBlockState(q).canBeReplaced()) continue;
            if (g.inventory.count(st -> st.is(it)) == 0) { boolean table = ensureCraftingTable(g, level, it); if (Crafting.craft(level, g.inventory, it, 1, table).made() == 0) continue; }
            g.tasks.add(new Task.GoTo(o, 1.5)); g.tasks.add(new Task.Place(q, it)); queued++;
            if (it == Items.CHEST) { g.myStations.add(q.immutable()); if (!g.storageChests.contains(q)) g.storageChests.add(q.immutable()); } else g.myStations.add(q.immutable());
        }
        for (BlockPos c : findAll(level, o, 2, b -> b.is(Blocks.CHEST), 4)) if (inside.test(c) && !g.storageChests.contains(c)) { g.storageChests.add(c.immutable()); g.myStations.add(c.immutable()); } // any chest in his place is his storage, wherever it ended up
        boolean torchIn = findAll(level, o, 2, b -> b.is(Blocks.TORCH) || b.is(Blocks.WALL_TORCH), 1).stream().anyMatch(inside);
        if (!torchIn && g.inventory.count(st -> st.is(Items.TORCH)) > 0 && level.getBlockState(at.get("torch")).canBeReplaced()) {
            g.tasks.add(new Task.GoTo(o.relative(front), 0.6)); g.tasks.add(new Task.Place(at.get("torch"), Items.TORCH)); queued++; // (not stood on the spot itself)
        }
        if (queued > 0) ClaudeMod.LOGGER.info("[Claude life] furnishing his place at {}: {} things to set", o.toShortString(), queued);
        return queued;
    }

